#!/usr/bin/env node
// Build the Vant subset bundle + CSS. Dev-time only; generated files are
// committed under web/static/legacy/lib/ and CI/deploy never runs Node.
//
//   npm install            # once
//   npm run build          # regenerate
//   npm run check          # fail if committed files are stale
import { build } from 'esbuild'
import { createHash } from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const repo = path.resolve(here, '../..')
const outDir = path.join(repo, 'web/static/legacy/lib')
const JS_OUT = 'vant.subset.min.js'
const CSS_OUT = 'vant.subset.min.css'
const MANIFEST_OUT = 'vant.subset.manifest.json'
const pkg = JSON.parse(fs.readFileSync(path.join(here, 'package.json'), 'utf8'))
const vantVersion = (pkg.devDependencies || {}).vant || ''

function componentsFromEntry() {
  const src = fs.readFileSync(path.join(here, 'src/entry.js'), 'utf8')
  const names = []
  for (const m of src.matchAll(/^import\s+\w+\s+from\s+'vant\/es\/([a-z-]+)\/index\.mjs'/gm)) {
    if (m[1] === 'toast') continue // functional API only, no <van-toast> in the template
    names.push('van-' + m[1])
  }
  return names.sort()
}

async function bundle() {
  const tmp = fs.mkdtempSync('/tmp/yxq-vant-')
  const result = await build({
    entryPoints: [path.join(here, 'src/entry.js')],
    outdir: tmp,
    entryNames: 'vant.subset.min',
    bundle: true,
    format: 'iife',
    globalName: 'vant',
    minify: true,
    legalComments: 'none',
    target: ['es2017'],
    loader: { '.css': 'css' },
    alias: { vue: path.join(here, 'src/vue-global.js') },
    banner: {
      js: `/* generated by tools/spa_vendor; vant=${vantVersion}; components=${componentsFromEntry().join(',')} */`,
    },
  })
  if (result.errors.length) throw new Error(result.errors.map((e) => e.text).join('\n'))
  const js = fs.readFileSync(path.join(tmp, JS_OUT))
  let css = fs.readFileSync(path.join(tmp, CSS_OUT)).toString('utf8')
  // Vant's icon CSS carries a base64 woff2 plus an external alicdn woff
  // fallback. The CSP is font-src 'self' data:, so the external URL only
  // produces a console error on every load; the base64 variant is enough.
  css = css.replace(/,\s*url\([^)]*alicdn\.com[^)]*\)\s*format\(["']woff["']\)/g, '')
  if (/alicdn\.com/.test(css)) throw new Error('vant subset CSS still references at.alicdn.com')
  const cssBuf = Buffer.from(css)
  fs.rmSync(tmp, { recursive: true, force: true })
  return { js, css: cssBuf }
}

function manifestFor(js, css) {
  return {
    generator: 'tools/spa_vendor/build.mjs',
    vant: vantVersion,
    components: componentsFromEntry(),
    js: { file: JS_OUT, bytes: js.length, sha256: createHash('sha256').update(js).digest('hex') },
    css: { file: CSS_OUT, bytes: css.length, sha256: createHash('sha256').update(css).digest('hex') },
  }
}

const { js, css } = await bundle()
const manifest = manifestFor(js, css)
const manifestText = JSON.stringify(manifest, null, 2) + '\n'
const check = process.argv.includes('--check')

if (check) {
  const problems = []
  for (const [file, want] of [[JS_OUT, js], [CSS_OUT, css], [MANIFEST_OUT, Buffer.from(manifestText)]]) {
    const p = path.join(outDir, file)
    if (!fs.existsSync(p)) problems.push(`${file}: missing`)
    else if (!fs.readFileSync(p).equals(Buffer.from(want))) problems.push(`${file}: stale`)
  }
  if (problems.length) {
    console.error('vant subset stale: ' + problems.join(', ') + '; run: cd tools/spa_vendor && npm run build')
    process.exit(1)
  }
  console.log(`vant subset OK (${manifest.components.length} components, js ${js.length}B, css ${css.length}B)`)
  process.exit(0)
}

fs.mkdirSync(outDir, { recursive: true })
fs.writeFileSync(path.join(outDir, JS_OUT), js)
fs.writeFileSync(path.join(outDir, CSS_OUT), css)
fs.writeFileSync(path.join(outDir, MANIFEST_OUT), manifestText)
console.log(`wrote ${JS_OUT} ${js.length}B, ${CSS_OUT} ${css.length}B, ${manifest.components.length} components`)
